}

import type { Warga, Petugas, Admin, Transaksi, Dukuh, RT, Pengeluaran, ContactMessage, Announcement, PublicStats, ParticipationStats, TransactionStatus } from '@/types';

// --- Mock Database ---
let dukuhs: Dukuh[] = [
    { id: 1, name: 'Rowosari' },
    { id: 2, name: 'Pencar' },
    { id: 3, name: 'Paten' },
    { id: 4, name: 'Adiloko' },
];

let rts: RT[] = [];
for (let i = 1; i <= 10; i++) {
    rts.push({ id: i, number: i < 10 ? `0${i}` : `${i}` });
}

const dummyNames = [
    "Budi Santoso", "Siti Aminah", "Agus Setiawan", "Dewi Lestari", "Eko Prasetyo",
    "Rina Wulandari", "Joko Susilo", "Sri Wahyuni", "Ahmad Fauzi", "Nurhayati",
    "Heri Purwanto", "Indah Sari", "Teguh Widodo", "Fitri Handayani", "Wahyu Hidayat",
    "Yuni Kartika", "Dian Purnomo", "Anisa Fitria", "Bayu Nugroho", "Ratna Juwita"
];

let wargas: Warga[] = [];
dukuhs.forEach(dukuh => {
    const activeRTs = rts.slice(0, 5); 
    activeRTs.forEach(rt => {
        for (let i = 1; i <= 3; i++) {
            const uniqueId = String(100000 + wargas.length);
            const dailyFee = 2000;
            wargas.push({
                id: uniqueId,
                name: dummyNames[wargas.length % dummyNames.length],
                rtId: rt.id,
                dukuhId: dukuh.id,
                dailyFee: dailyFee,
                totalDebt: Math.random() > 0.8 ? dailyFee * Math.floor(Math.random() * 5) : 0 // Some residents start with debt
            });
        }
    });
});

let petugases: Petugas[] = [
    { id: 'petugas01', name: 'Agus', phone: '081234567890', pin: '1234' },
    { id: 'petugas02', name: 'Bambang', phone: '081234567891', pin: '5678' },
];

let admins: Admin[] = [
    { id: 'admin01', username: 'admin', name: 'Admin Desa' },
];

let adminPassword = 'password';
let transactions: Transaksi[] = [];
let pengeluarans: Pengeluaran[] = [];

let schedule: Record<string, number[] | 'libur'> = {
    Senin: [1, 2], Selasa: [4, 3], Rabu: [1, 2], Kamis: [4, 3], Jumat: 'libur', Sabtu: [1, 2], Minggu: [4, 3],
};

let messages: ContactMessage[] = [];
let announcements: Announcement[] = [];

const delay = (ms: number) => new Promise(res => setTimeout(res, ms));

export const getWargaById = async (id: string): Promise<Warga | null> => {
    await delay(200);
    return wargas.find(w => w.id === id) || null;
};

export const getTransactionsByWargaId = async (wargaId: string, days: number): Promise<Transaksi[]> => {
    const limitDate = new Date();
    limitDate.setDate(limitDate.getDate() - days);
    return transactions.filter(tx => tx.wargaId === wargaId && tx.timestamp >= limitDate).sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime());
};

export const getPublicDashboardStats = async (): Promise<PublicStats> => {
    const today = new Date();
    const transactionsThisMonth = transactions.filter(tx => tx.status === 'LUNAS' && tx.timestamp.getMonth() === today.getMonth());
    return {
        totalWarga: wargas.length,
        totalTransaksiBulanIni: transactionsThisMonth.length,
        totalDanaTerkumpulBulanIni: transactionsThisMonth.reduce((sum, tx) => sum + tx.amount, 0)
    };
};

export const getActiveAnnouncements = async (): Promise<Announcement[]> => announcements.filter(a => a.isActive);

export const loginPetugas = async (pin: string): Promise<Petugas | null> => petugases.find(p => p.pin === pin) || null;
export const loginAdmin = async (u: string, p: string): Promise<Admin | null> => (u === 'admin' && p === adminPassword) ? admins[0] : null;

export const createTransaksi = async (txData: {wargaId: string, petugasId: string, amount: number, status?: TransactionStatus}): Promise<Transaksi> => {
    await delay(300);
    const status = txData.status || 'LUNAS';
    const newTx: Transaksi = {
        ...txData,
        status,
        id: `tx${Date.now()}`,
        timestamp: new Date(),
    };

    // Update Warga Debt if needed
    const warga = wargas.find(w => w.id === txData.wargaId);
    if (warga) {
        if (status === 'HUTANG') {
            warga.totalDebt += txData.amount;
        } else if (status === 'LUNAS') {
            // Logic if paying off debt could go here, but for now we just record the daily fee
        }
    }

    transactions.unshift(newTx);
    return newTx;
};

// Admin API
export const getAdminDashboardStats = async () => {
    const totalRevenue = transactions.filter(tx => tx.status === 'LUNAS').reduce((sum, tx) => sum + tx.amount, 0);
    const totalDebt = wargas.reduce((sum, w) => sum + (w.totalDebt || 0), 0);
    const totalExpense = pengeluarans.reduce((sum, p) => sum + p.amount, 0);
    return {
        totalRevenue,
        totalExpense,
        balance: totalRevenue - totalExpense,
        totalWarga: wargas.length,
        totalPetugas: petugases.length,
        totalDebt,
        monthlyRevenue: [] // simplified
    };
};

export const getAllWarga = async (): Promise<Warga[]> => [...wargas];
export const updateWarga = async (id: string, data: Warga): Promise<Warga> => {
    const idx = wargas.findIndex(w => w.id === id);
    if (idx > -1) { wargas[idx] = data; return wargas[idx]; }
    throw new Error('Not found');
};
export const createWarga = async (d: Omit<Warga, 'id' | 'totalDebt'>): Promise<Warga> => {
    const nw: Warga = { ...d, id: String(100000 + wargas.length), totalDebt: 0 };
    wargas.push(nw); return nw;
};
export const deleteWarga = async (id: string) => { wargas = wargas.filter(w => w.id !== id); };

export const getAllDukuh = async (): Promise<Dukuh[]> => [...dukuhs];
export const getDukuhById = (id: number) => dukuhs.find(d => d.id === id) || null;
export const getAllRT = async (): Promise<RT[]> => [...rts];
export const getRTById = (id: number) => rts.find(r => r.id === id) || null;

export const getReports = async (f: any): Promise<any[]> => {
    return transactions.map(tx => {
        const w = wargas.find(w => w.id === tx.wargaId);
        const p = petugases.find(p => p.id === tx.petugasId);
        return {
            ...tx,
            wargaName: w?.name || 'N/A',
            petugasName: p?.name || 'N/A',
            dukuhName: dukuhs.find(d => d.id === w?.dukuhId)?.name || 'N/A',
            rtNumber: rts.find(r => r.id === w?.rtId)?.number || 'N/A'
        };
    });
};

export const getPengeluaran = async (f: any) => pengeluarans;
export const getScheduleForToday = async () => {
    const day = ['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'][new Date().getDay()];
    const s = schedule[day];
    return { isHoliday: s === 'libur', dukuhIds: s === 'libur' ? [] : s, dukuhNames: [] };
};
export const checkIfWargaPaidToday = async (id: string) => {
    const today = new Date().toDateString();
    return transactions.some(tx => tx.wargaId === id && tx.timestamp.toDateString() === today);
};
export const getUnpaidWargaForToday = async () => wargas; // Simplified
export const getPetugasDailySummary = async (id: string) => ({ total: 0, count: 0 });
export const getMessages = async () => [];
export const getAnnouncements = async () => [];
export const getParticipationReport = async (m: number, y: number) => [];
export const getUnpaidWargaForDate = async (d: Date) => [];
export const getScheduleForDate = async (d: Date) => ({ isHoliday: false, dukuhNames: [] });
export const getSchedule = async () => schedule;
export const updateSchedule = async (d: string, s: any) => { schedule[d] = s; return schedule; };
export const deleteTransaksi = async (id: string) => { transactions = transactions.filter(t => t.id !== id); };

import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import type { Warga, TransactionStatus } from '@/types';
import { getWargaById, createTransaksi, getDukuhById, getRTById, checkIfWargaPaidToday, getScheduleForToday } from '@/services/api';
import { useAuth } from '@/context/AuthContext';
import { CheckCircleIcon, QrCodeIcon } from '@/components/icons';
import Modal from '@/components/Modal';

const PetugasScanPage: React.FC = () => {
    const [mode, setMode] = useState<'scan' | 'manual'>('manual');
    const [wargaId, setWargaId] = useState('');
    const [warga, setWarga] = useState<Warga | null>(null);
    const [hasPaidToday, setHasPaidToday] = useState(false);
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const [success, setSuccess] = useState(false);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const { petugas } = useAuth();

    const resetState = useCallback(() => {
        setWarga(null);
        setWargaId('');
        setError('');
        setSuccess(false);
        setLoading(false);
        setHasPaidToday(false);
    }, []);

    const fetchWarga = useCallback(async (id: string) => {
        setLoading(true);
        setError('');
        try {
            const data = await getWargaById(id);
            if (data) {
                setWarga(data);
                const paidToday = await checkIfWargaPaidToday(id);
                setHasPaidToday(paidToday);
            } else {
                setError(`ID Warga "${id}" tidak ditemukan.`);
            }
        } catch (err) {
            setError('Gagal memuat data warga.');
        } finally {
            setLoading(false);
        }
    }, []);

    const handleManualSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (wargaId.length === 6) {
            fetchWarga(wargaId);
        } else {
            setError('ID Warga harus 6 digit.');
        }
    };

    const handleSavePayment = async (status: TransactionStatus) => {
        if (!warga || !petugas) return;
        setLoading(true);
        try {
            await createTransaksi({
                wargaId: warga.id,
                petugasId: petugas.id,
                amount: warga.dailyFee,
                status: status
            });
            setSuccess(true);
            setIsModalOpen(true);
            setTimeout(() => {
                setIsModalOpen(false);
                resetState();
            }, 2000);
        } catch (err: any) {
            setError(err.message || 'Gagal menyimpan.');
        } finally {
            setLoading(false);
        }
    };

    const getDukuhName = (id: number) => getDukuhById(id)?.name || 'N/A';
    const getRTNumber = (id: number) => getRTById(id)?.number || 'N/A';

    return (
        <div className="flex-grow p-4 max-w-md mx-auto w-full">
            {!warga && (
                <div className="animate-fade-in space-y-4">
                    <form onSubmit={handleManualSubmit} className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                        <label className="block text-slate-700 font-semibold mb-2">Input Manual ID Warga</label>
                        <input
                            type="tel"
                            value={wargaId}
                            onChange={(e) => setWargaId(e.target.value.replace(/\D/g, ''))}
                            maxLength={6}
                            placeholder="Contoh: 100001"
                            className="w-full text-lg px-4 py-3 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary"
                        />
                        <button type="submit" disabled={loading} className="w-full mt-4 bg-primary text-white font-bold py-3 rounded-lg hover:bg-primary-focus">
                            Cari Warga
                        </button>
                    </form>
                </div>
            )}

            {warga && !success && (
                <div className="bg-white p-6 rounded-xl shadow-lg border border-slate-200 animate-slide-in-up">
                    <h2 className="text-2xl font-bold text-slate-800">{warga.name}</h2>
                    <p className="text-slate-500">ID: {warga.id} | RT {getRTNumber(warga.rtId)}, {getDukuhName(warga.dukuhId)}</p>

                    <div className="mt-6 p-4 bg-slate-50 rounded-xl border border-slate-100">
                        <p className="text-sm text-slate-500 text-center">Tarif Harian</p>
                        <p className="text-4xl font-bold text-slate-800 text-center">
                            {new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(warga.dailyFee)}
                        </p>
                        {warga.totalDebt > 0 && (
                            <p className="text-center text-red-600 font-bold mt-2 animate-pulse">
                                Total Tunggakan: {new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(warga.totalDebt)}
                            </p>
                        )}
                    </div>

                    {hasPaidToday && (
                        <div className="mt-4 p-3 bg-green-100 text-green-700 rounded-lg text-center text-sm font-bold">
                            Warga ini sudah membayar hari ini.
                        </div>
                    )}

                    <div className="mt-8 space-y-3">
                        <button 
                            onClick={() => handleSavePayment('LUNAS')} 
                            disabled={loading || hasPaidToday} 
                            className="w-full bg-primary text-white font-bold py-4 rounded-xl shadow-lg hover:bg-primary-focus transition-all disabled:opacity-50"
                        >
                            Bayar Tunai (Lunas)
                        </button>
                        <button 
                            onClick={() => handleSavePayment('HUTANG')} 
                            disabled={loading || hasPaidToday} 
                            className="w-full bg-amber-500 text-white font-bold py-4 rounded-xl shadow-lg hover:bg-amber-600 transition-all disabled:opacity-50"
                        >
                            Catat Tunggakan (Hutang)
                        </button>
                        <button onClick={resetState} className="w-full text-slate-500 font-semibold py-2">
                            Batal
                        </button>
                    </div>
                </div>
            )}

            <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="Berhasil">
                <div className="text-center py-4">
                    <CheckCircleIcon className="text-6xl text-success mx-auto mb-4" />
                    <p className="text-xl font-bold text-slate-800">Catatan Berhasil Disimpan</p>
                </div>
            </Modal>
        </div>
    );
};

export default PetugasScanPage;

import React, { useState, useEffect, useMemo } from 'react';
import type { Warga, Dukuh, RT } from '@/types';
import { getAllWarga, getAllDukuh, getAllRT, createWarga, updateWarga, deleteWarga } from '@/services/api';
import Modal from '@/components/Modal';
import { TrashIcon, PencilIcon, SearchIcon, ChevronDownIcon } from '@/components/icons';

const AdminWargaPage: React.FC = () => {
    const [wargaList, setWargaList] = useState<Warga[]>([]);
    const [dukuhList, setDukuhList] = useState<Dukuh[]>([]);
    const [rtList, setRtList] = useState<RT[]>([]);
    const [loading, setLoading] = useState(true);
    const [filters, setFilters] = useState({ search: '', dukuhId: 'all' });

    const fetchData = async () => {
        setLoading(true);
        const [w, d, r] = await Promise.all([getAllWarga(), getAllDukuh(), getAllRT()]);
        setWargaList(w);
        setDukuhList(d);
        setRtList(r);
        setLoading(false);
    };

    useEffect(() => { fetchData(); }, []);

    const filteredWarga = useMemo(() => {
        return wargaList.filter(w => {
            const matchSearch = w.name.toLowerCase().includes(filters.search.toLowerCase()) || w.id.includes(filters.search);
            const matchDukuh = filters.dukuhId === 'all' || w.dukuhId === Number(filters.dukuhId);
            return matchSearch && matchDukuh;
        });
    }, [wargaList, filters]);

    const getDukuhName = (id: number) => dukuhList.find(d => d.id === id)?.name || 'N/A';
    const getRTNumber = (id: number) => rtList.find(r => r.id === id)?.number || 'N/A';

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <h1 className="text-2xl font-bold text-slate-800">Data Warga</h1>
                <button className="bg-primary text-white px-4 py-2 rounded-lg font-bold">+ Warga Baru</button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-white p-4 rounded-xl border border-slate-200">
                <div className="relative">
                    <SearchIcon className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                    <input 
                        type="text" 
                        placeholder="Cari nama atau ID..." 
                        className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary"
                        onChange={(e) => setFilters({...filters, search: e.target.value})}
                    />
                </div>
                <select 
                    className="p-2 border border-slate-200 rounded-lg focus:outline-none"
                    onChange={(e) => setFilters({...filters, dukuhId: e.target.value})}
                >
                    <option value="all">Semua Dukuh</option>
                    {dukuhList.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                </select>
            </div>

            <div className="bg-white rounded-xl border border-slate-200 overflow-hidden shadow-sm">
                <table className="w-full text-sm text-left">
                    <thead className="bg-slate-50 border-b border-slate-200 text-slate-500 uppercase text-xs font-bold">
                        <tr>
                            <th className="p-4">ID</th>
                            <th className="p-4">Nama</th>
                            <th className="p-4">Wilayah</th>
                            <th className="p-4 text-right">Tarif</th>
                            <th className="p-4 text-right">Tunggakan</th>
                            <th className="p-4 text-center">Aksi</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {filteredWarga.map(w => (
                            <tr key={w.id} className="hover:bg-slate-50 transition-colors">
                                <td className="p-4 font-mono text-slate-500">{w.id}</td>
                                <td className="p-4 font-bold text-slate-800">{w.name}</td>
                                <td className="p-4 text-slate-500">RT {getRTNumber(w.rtId)}, {getDukuhName(w.dukuhId)}</td>
                                <td className="p-4 text-right font-mono">Rp{w.dailyFee.toLocaleString()}</td>
                                <td className={`p-4 text-right font-mono font-bold ${w.totalDebt > 0 ? 'text-red-500' : 'text-slate-400'}`}>
                                    Rp{w.totalDebt.toLocaleString()}
                                </td>
                                <td className="p-4 text-center">
                                    <div className="flex justify-center gap-2">
                                        <button className="p-1 text-blue-500"><PencilIcon /></button>
                                        <button className="p-1 text-red-500"><TrashIcon /></button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default AdminWargaPage;

