export default PetugasScanPage;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import type { FC } from 'react';
import type { Warga, TransactionStatus } from '@/types';
import { getWargaById, createTransaksi, payDebt, getDukuhById, getRTById, checkIfWargaPaidToday } from '@/services/api';
import { useAuth } from '@/context/AuthContext';
import { CheckCircleIcon, QrCodeIcon, SearchIcon, XIcon, BanknotesIcon } from '@/components/icons';
import Modal from '@/components/Modal';
import jsQR from 'jsqr';

const PetugasScanPage: FC = () => {
    const [mode, setMode] = useState<'scan' | 'manual'>('scan');
    const [wargaId, setWargaId] = useState('');
    const [warga, setWarga] = useState<Warga | null>(null);
    const [hasPaidToday, setHasPaidToday] = useState(false);
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const [success, setSuccess] = useState(false);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [modalTitle, setModalTitle] = useState('Berhasil');

    const videoRef = useRef<HTMLVideoElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [isScanning, setIsScanning] = useState(false);
    const isScanningRef = useRef(false); // Used to avoid stale closures in requestAnimationFrame

    const { petugas } = useAuth();

    const resetState = useCallback(() => {
        setWarga(null);
        setWargaId('');
        setError('');
        setSuccess(false);
        setLoading(false);
        setHasPaidToday(false);
        if (mode === 'scan') {
            setIsScanning(true);
            isScanningRef.current = true;
        }
    }, [mode]);

    const fetchWarga = useCallback(async (id: string) => {
        setIsScanning(false);
        isScanningRef.current = false;
        setLoading(true);
        setError('');

        try {
            const data = await getWargaById(id);
            if (data) {
                setWarga(data);
                const paidToday = await checkIfWargaPaidToday(id);
                setHasPaidToday(paidToday);
            } else {
                setError(`ID Warga "${id}" tidak ditemukan.`);
                if (mode === 'scan') {
                    setTimeout(() => {
                        setIsScanning(true);
                        isScanningRef.current = true;
                    }, 3000);
                }
            }
        } catch (err) {
            setError('Gagal memuat data warga.');
            if (mode === 'scan') {
                setTimeout(() => {
                    setIsScanning(true);
                    isScanningRef.current = true;
                }, 3000);
            }
        } finally {
            setLoading(false);
        }
    }, [mode]);

    // QR Scanner Logic
    useEffect(() => {
        let stream: MediaStream | null = null;
        let animationFrameId: number;

        const tick = () => {
            if (!isScanningRef.current) {
                animationFrameId = requestAnimationFrame(tick);
                return;
            }

            if (videoRef.current && videoRef.current.readyState === videoRef.current.HAVE_ENOUGH_DATA && canvasRef.current) {
                const canvas = canvasRef.current;
                const video = videoRef.current;

                canvas.height = video.videoHeight;
                canvas.width = video.videoWidth;

                const ctx = canvas.getContext('2d', { willReadFrequently: true });

                if (ctx) {
                    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
                    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);

                    try {
                        const code = jsQR(imageData.data, imageData.width, imageData.height, {
                            inversionAttempts: "dontInvert",
                        });

                        if (code && code.data) {
                            isScanningRef.current = false;
                            setIsScanning(false);
                            fetchWarga(code.data);
                            return; 
                        }
                    } catch (err) {
                        console.error("jsQR error:", err);
                    }
                }
            }
            animationFrameId = requestAnimationFrame(tick);
        };

        const startCamera = async () => {
            if (mode !== 'scan' || warga || success) return;

            try {
                stream = await navigator.mediaDevices.getUserMedia({ 
                    video: { 
                        facingMode: 'environment',
                        width: { ideal: 1280 },
                        height: { ideal: 720 }
                    } 
                });

                if (videoRef.current) {
                    videoRef.current.srcObject = stream;
                    videoRef.current.onloadedmetadata = () => {
                        videoRef.current?.play().catch(e => console.error("Play error:", e));
                        setIsScanning(true);
                        isScanningRef.current = true;
                        tick();
                    };
                }
            } catch (err) {
                console.error("Camera error:", err);
                setError('Tidak dapat mengakses kamera. Pastikan izin kamera diberikan.');
                setMode('manual');
            }
        };

        if (mode === 'scan' && !warga && !success) {
            startCamera();
        }

        return () => {
            if (stream) {
                stream.getTracks().forEach(track => track.stop());
            }
            cancelAnimationFrame(animationFrameId);
            isScanningRef.current = false;
        };
    }, [mode, warga, success, fetchWarga]);

    const handleManualSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (wargaId.length === 6) {
            fetchWarga(wargaId);
        } else {
            setError('ID Warga harus 6 digit.');
        }
    };

    const handleSavePayment = async (status: TransactionStatus) => {
        if (!warga || !petugas) return;
        setLoading(true);
        try {
            await createTransaksi({
                wargaId: warga.id,
                petugasId: petugas.id,
                amount: warga.dailyFee,
                status: status
            });
            setModalTitle(status === 'LUNAS' ? 'Pembayaran Berhasil' : 'Tunggakan Dicatat');
            setSuccess(true);
            setIsModalOpen(true);
            setTimeout(() => {
                setIsModalOpen(false);
                resetState();
            }, 2000);
        } catch (err: any) {
            setError(err.message || 'Gagal menyimpan.');
        } finally {
            setLoading(false);
        }
    };

    const handlePayDebt = async () => {
        if (!warga || !petugas) return;
        if (warga.totalDebt <= 0) return;

        setLoading(true);
        try {
            await payDebt(warga.id, petugas.id, warga.totalDebt);
            setModalTitle('Pelunasan Berhasil');
            setSuccess(true);
            setIsModalOpen(true);
            setTimeout(() => {
                setIsModalOpen(false);
                resetState();
            }, 2000);
        } catch (err: any) {
            setError(err.message || 'Gagal melunasi tunggakan.');
        } finally {
            setLoading(false);
        }
    };

    const getDukuhName = (id: number) => getDukuhById(id)?.name || 'N/A';
    const getRTNumber = (id: number) => getRTById(id)?.number || 'N/A';

    return (
        <div className="flex-grow p-4 max-w-md mx-auto w-full">
            {!warga && (
                <div className="flex bg-white p-1 rounded-xl shadow-sm border border-slate-200 mb-6">
                    <button 
                        onClick={() => setMode('scan')}
                        className={`flex-1 py-2 px-4 rounded-lg font-bold text-sm transition-all flex items-center justify-center gap-2 ${mode === 'scan' ? 'bg-primary text-white shadow-md' : 'text-slate-500'}`}
                    >
                        <QrCodeIcon className="text-lg" /> Scan QR
                    </button>
                    <button 
                        onClick={() => setMode('manual')}
                        className={`flex-1 py-2 px-4 rounded-lg font-bold text-sm transition-all flex items-center justify-center gap-2 ${mode === 'manual' ? 'bg-primary text-white shadow-md' : 'text-slate-500'}`}
                    >
                        <SearchIcon className="text-lg" /> Manual
                    </button>
                </div>
            )}

            {!warga && mode === 'scan' && (
                <div className="relative aspect-square w-full bg-slate-900 rounded-3xl overflow-hidden shadow-2xl border-4 border-white animate-fade-in">
                    <video 
                        ref={videoRef} 
                        className="w-full h-full object-cover" 
                        playsInline 
                        autoPlay 
                        muted 
                    />
                    <canvas ref={canvasRef} className="hidden" />
                    <div className="absolute inset-0 border-[40px] border-slate-900/40 pointer-events-none">
                        <div className="w-full h-full border-2 border-primary/50 rounded-xl relative">
                            <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-primary"></div>
                            <div className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 border-primary"></div>
                            <div className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 border-primary"></div>
                            <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-primary"></div>
                            <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-primary to-transparent animate-[scan_2s_linear_infinite]"></div>
                        </div>
                    </div>
                    <div className="absolute bottom-6 left-0 right-0 text-center">
                        <p className="text-white text-xs font-bold bg-slate-900/60 inline-block px-4 py-2 rounded-full backdrop-blur-md">
                            Arahkan kamera ke QR Code warga
                        </p>
                    </div>
                </div>
            )}

            {!warga && mode === 'manual' && (
                <div className="animate-fade-in space-y-4">
                    <form onSubmit={handleManualSubmit} className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                        <label className="block text-slate-700 font-semibold mb-2">Input Manual ID Warga</label>
                        <input
                            type="tel"
                            value={wargaId}
                            onChange={(e) => setWargaId(e.target.value.replace(/\D/g, ''))}
                            maxLength={6}
                            placeholder="Contoh: 100001"
                            className="w-full text-lg px-4 py-3 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary"
                            autoFocus
                        />
                        <button type="submit" disabled={loading} className="w-full mt-4 bg-primary text-white font-bold py-3 rounded-lg hover:bg-primary-focus">
                            Cari Warga
                        </button>
                    </form>
                </div>
            )}

            {error && !warga && (
                <div className="mt-4 p-4 bg-red-50 border border-red-200 text-red-600 rounded-xl text-sm font-medium flex items-start gap-3 animate-shake">
                    <XIcon className="mt-0.5" />
                    <p>{error}</p>
                </div>
            )}

            {warga && !success && (
                <div className="bg-white p-6 rounded-3xl shadow-xl border border-slate-200 animate-slide-in-up">
                    <div className="text-center mb-6">
                        <div className="w-16 h-16 bg-primary-light rounded-2xl flex items-center justify-center mx-auto mb-3">
                            <QrCodeIcon className="text-3xl text-primary" />
                        </div>
                        <h2 className="text-2xl font-bold text-slate-800">{warga.name}</h2>
                        <p className="text-slate-500 font-medium">ID: {warga.id} • RT {getRTNumber(warga.rtId)}, {getDukuhName(warga.dukuhId)}</p>
                    </div>

                    <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100 mb-6">
                        <div className="flex flex-col items-center gap-1">
                            <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Tarif Sampah Hari Ini</p>
                            <p className="text-4xl font-extrabold text-slate-800">
                                {new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(warga.dailyFee)}
                            </p>
                        </div>

                        {warga.totalDebt > 0 && (
                            <div className="mt-4 pt-4 border-t border-slate-200 text-center">
                                <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mb-1">Total Tunggakan Lama</p>
                                <p className="text-xl font-bold text-red-600">
                                    {new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(warga.totalDebt)}
                                </p>
                            </div>
                        )}
                    </div>

                    <div className="space-y-3">
                        <div className="grid grid-cols-1 gap-3">
                            <button 
                                onClick={() => handleSavePayment('LUNAS')} 
                                disabled={loading || hasPaidToday} 
                                className="w-full bg-emerald-500 text-white font-bold py-4 rounded-2xl shadow-lg shadow-emerald-500/20 hover:bg-emerald-600 transition-all disabled:opacity-50 flex items-center justify-center gap-2"
                            >
                                <CheckCircleIcon /> {hasPaidToday ? 'Sudah Tercatat Hari Ini' : 'Bayar Tunai (Hari Ini)'}
                            </button>

                            {!hasPaidToday && (
                                <button 
                                    onClick={() => handleSavePayment('HUTANG')} 
                                    disabled={loading} 
                                    className="w-full bg-amber-500 text-white font-bold py-4 rounded-2xl shadow-lg shadow-amber-500/20 hover:bg-amber-600 transition-all disabled:opacity-50"
                                >
                                    Catat Tunggakan (Hari Ini)
                                </button>
                            )}

                            {warga.totalDebt > 0 && (
                                <button 
                                    onClick={handlePayDebt} 
                                    disabled={loading} 
                                    className="w-full bg-indigo-500 text-white font-bold py-4 rounded-2xl shadow-lg shadow-indigo-500/20 hover:bg-indigo-600 transition-all disabled:opacity-50 flex items-center justify-center gap-2"
                                >
                                    <BanknotesIcon /> Bayar Pelunasan Tunggakan
                                </button>
                            )}
                        </div>

                        <button onClick={resetState} className="w-full text-slate-400 font-bold py-2 hover:text-slate-600">
                            Batal
                        </button>
                    </div>
                </div>
            )}

            <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={modalTitle}>
                <div className="text-center py-6">
                    <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4 animate-bounce">
                        <CheckCircleIcon className="text-5xl text-success" />
                    </div>
                    <p className="text-2xl font-extrabold text-slate-800">{modalTitle}!</p>
                    <p className="text-slate-500 mt-1">Sistem telah memperbarui data warga.</p>
                </div>
            </Modal>

            <style>{`
                @keyframes scan {
                    0% { top: 0; }
                    50% { top: 100%; }
                    100% { top: 0; }
                }
                .animate-shake {
                    animation: shake 0.5s cubic-bezier(.36,.07,.19,.97) both;
                }
                @keyframes shake {
                    10%, 90% { transform: translate3d(-1px, 0, 0); }
                    20%, 80% { transform: translate3d(2px, 0, 0); }
                    30%, 50%, 70% { transform: translate3d(-4px, 0, 0); }
                    40%, 60% { transform: translate3d(4px, 0, 0); }
                }
            `}</style>
        </div>
    );
};

export default PetugasScanPage;

import React, { useState, useEffect, useMemo, FC } from 'react';
import { getReports, getAllDukuh, getAllRT, getPengeluaran, getUnpaidWargaForDate, getScheduleForDate, getDukuhById, getRTById, getParticipationReport } from '@/services/api';
import { exportToExcel } from '@/services/excel';
import type { Transaksi, Dukuh, RT, Pengeluaran, Warga, ParticipationStats } from '@/types';
import { UserSlashIcon, FileExcelIcon, EyeIcon, ChevronDownIcon } from '@/components/icons';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from 'recharts';
import Modal from '@/components/Modal';

interface ReportRow extends Transaksi {
    wargaName: string;
    petugasName: string;
    dukuhName: string;
    rtNumber: string;
}

const printReport = (title: string, content: string) => {
    const printWindow = window.open('', '_blank');
    if (printWindow) {
        printWindow.document.write(`
            <html>
                <head>
                    <title>${title}</title>
                    <style>
                        body { font-family: 'Inter', sans-serif; color: #333; -webkit-print-color-adjust: exact; }
                        @page { size: F4; margin: 1.5cm; }

                        .print-header { display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid #0d9488; padding-bottom: 10px; margin-bottom: 20px; }
                        .print-header h1 { font-size: 24px; color: #0d9488; margin: 0; }
                        .print-header p { margin: 0; font-size: 10pt; color: #666; }

                        h2 { font-size: 20px; border-bottom: 1px solid #eee; padding-bottom: 5px; margin-bottom: 1rem; color: #333; }
                        h3 { font-size: 16px; margin-top: 1.5rem; margin-bottom: 0.5rem; color: #333; }

                        table { width: 100%; border-collapse: collapse; margin-top: 1rem; }
                        th, td { border: 1px solid #ddd; padding: 8px; text-align: left; font-size: 10pt; }
                        thead { background-color: #f1f5f9; color: #333; }
                        tr { page-break-inside: avoid; }

                        .summary-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 1rem; margin-bottom: 1rem; }
                        .summary-card { border: 1px solid #e5e7eb; background-color: #f9fafb; padding: 15px; border-radius: 8px; text-align: center; }
                        .summary-card p { margin: 0; font-size: 12px; color: #666; }
                        .summary-card strong { display: block; font-size: 18px; margin-top: 4px; }
                        .pemasukan { color: #15803d; }
                        .pengeluaran { color: #b91c1c; }
                        .saldo { color: #0d9488; }

                        .currency { text-align: right; font-family: 'Courier New', Courier, monospace; }

                        .print-footer { text-align: center; margin-top: 2rem; font-size: 8pt; color: #9ca3af; }

                        @media print {
                            .no-print { display: none; }
                        }
                    </style>
                </head>
                <body>
                    ${content}
                    <script>
                        window.addEventListener('load', () => {
                            window.print();
                            window.close();
                        });
                    </script>
                </body>
            </html>
        `);
        printWindow.document.close();
    }
};

const LaporanHarian: FC = () => {
    const [reports, setReports] = useState<ReportRow[]>([]);
    const [pengeluaranList, setPengeluaranList] = useState<Pengeluaran[]>([]);
    const [loading, setLoading] = useState(false);
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

    useEffect(() => {
        const fetchReports = async () => {
            setLoading(true);
            const selectedDate = new Date(date);
            try {
                const [reportData, pengeluaranData] = await Promise.all([
                    getReports({ startDate: selectedDate, endDate: selectedDate }),
                    getPengeluaran({ startDate: selectedDate, endDate: selectedDate })
                ]);
                setReports(reportData);
                setPengeluaranList(pengeluaranData);
            } catch (error) {
                console.error("Failed to fetch daily reports", error);
            } finally {
                setLoading(false);
            }
        };
        fetchReports();
    }, [date]);

    const totalPemasukan = useMemo(() => reports.reduce((sum, item) => sum + item.amount, 0), [reports]);
    const totalPengeluaran = useMemo(() => pengeluaranList.reduce((sum, item) => sum + item.amount, 0), [pengeluaranList]);
    const saldo = totalPemasukan - totalPengeluaran;

    const handleExportExcel = () => {
        const data = reports.map(r => ({
            Tanggal: new Date(r.timestamp).toLocaleDateString(),
            Waktu: new Date(r.timestamp).toLocaleTimeString(),
            Warga: r.wargaName,
            Dukuh: r.dukuhName,
            RT: r.rtNumber,
            Petugas: r.petugasName,
            Jumlah: r.amount
        }));
        exportToExcel(data, `Laporan_Harian_${date}`);
    };

    const handlePrint = () => {
        const formattedDate = new Date(date + 'T00:00:00').toLocaleDateString('id-ID', { dateStyle: 'full' });
        const title = `Laporan Harian - ${formattedDate}`;

        let pemasukanRows = reports.map(item => `
            <tr>
                <td>${new Date(item.timestamp).toLocaleTimeString('id-ID')}</td>
                <td>${item.wargaName} (RT ${item.rtNumber}, ${item.dukuhName})</td>
                <td>${item.petugasName}</td>
                <td class="currency">${new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR' }).format(item.amount)}</td>
            </tr>
        `).join('');

        let pengeluaranRows = pengeluaranList.map(item => `
            <tr>
                <td>${new Date(item.date).toLocaleTimeString('id-ID')}</td>
                <td colspan="2">${item.description}</td>
                <td class="currency">${new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR' }).format(item.amount)}</td>
            </tr>
        `).join('');

        const content = `
            <div class="print-header"><h1>SapaDesa</h1><p>Laporan Keuangan</p></div>
            <h2>${title}</h2>
            <div class="summary-grid">
                <div class="summary-card"><p>Total Pemasukan</p><strong class="pemasukan">${new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR' }).format(totalPemasukan)}</strong></div>
                <div class="summary-card"><p>Total Pengeluaran</p><strong class="pengeluaran">${new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR' }).format(totalPengeluaran)}</strong></div>
                <div class="summary-card"><p>Saldo Akhir</p><strong class="saldo">${new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR' }).format(saldo)}</strong></div>
            </div>

            <h3>Rincian Pemasukan</h3>
            <table>
                <thead><tr><th>Waktu</th><th>Warga</th><th>Petugas</th><th class="currency">Jumlah</th></tr></thead>
                <tbody>${reports.length > 0 ? pemasukanRows : '<tr><td colspan="4" style="text-align: center;">Tidak ada pemasukan.</td></tr>'}</tbody>
            </table>

            <h3>Rincian Pengeluaran</h3>
            <table>
                <thead><tr><th>Waktu</th><th colspan="2">Keterangan</th><th class="currency">Jumlah</th></tr></thead>
                <tbody>${pengeluaranList.length > 0 ? pengeluaranRows : '<tr><td colspan="4" style="text-align: center;">Tidak ada pengeluaran.</td></tr>'}</tbody>
            </table>
            <div class="print-footer"><p>Dicetak pada ${new Date().toLocaleString('id-ID')}</p></div>
        `;
        printReport(title, content);
    };

    return (
        <div className="animate-fade-in space-y-6">
            <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200/80 flex gap-4 items-center">
                <div className="flex-grow">
                     <label className="block text-sm font-medium text-slate-700 mb-1">Pilih Tanggal</label>
                     <input type="date" value={date} onChange={e => setDate(e.target.value)} className="p-2 border border-slate-300 rounded-lg w-full" />
                </div>
                <div className="flex items-end gap-2">
                    <button onClick={handleExportExcel} className="self-end bg-white text-emerald-600 border border-emerald-200 font-semibold px-4 py-2 rounded-lg hover:bg-emerald-50 transition-colors flex items-center gap-2"><FileExcelIcon /> Export Excel</button>
                    <button onClick={handlePrint} className="self-end bg-primary text-primary-content font-semibold px-4 py-2 rounded-lg shadow-sm shadow-primary/30 hover:bg-primary-focus transition-colors">Cetak</button>
                </div>
            </div>
            <ReportSummary totalPemasukan={totalPemasukan} totalPengeluaran={totalPengeluaran} saldo={saldo} count={reports.length} />
            <ReportTable reports={reports} loading={loading} />
        </div>
    );
};

const LaporanBulanan: FC = () => {
    const [reports, setReports] = useState<ReportRow[]>([]);
    const [pengeluaranList, setPengeluaranList] = useState<Pengeluaran[]>([]);
    const [loading, setLoading] = useState(false);
    const [month, setMonth] = useState(new Date().toISOString().slice(0, 7));

    useEffect(() => {
        const fetchReports = async () => {
            const [year, monthNum] = month.split('-').map(Number);
            const startDate = new Date(year, monthNum - 1, 1);
            const endDate = new Date(year, monthNum, 0);
            setLoading(true);
            try {
                 const [reportData, pengeluaranData] = await Promise.all([
                    getReports({ startDate, endDate }),
                    getPengeluaran({ startDate, endDate })
                ]);
                setReports(reportData);
                setPengeluaranList(pengeluaranData);
